#!/usr/bin/env python3
"""Run selected exact pinned classes/bodies; not full AsyncTCP/FreeRTOS execution."""
import pathlib,sys,argparse,json,subprocess,re
sys.dont_write_bytecode=True
from prepare_sources import ROOT,frameworks,load,sha
V=load(ROOT/'tests/stage28v/run_tests.py','v_test')
p=argparse.ArgumentParser();p.add_argument('--user-dir',type=pathlib.Path,required=True);p.add_argument('--output-dir',type=pathlib.Path,required=True);a=p.parse_args();assert not a.output_dir.exists() and not a.output_dir.resolve().is_relative_to(ROOT);a.output_dir.mkdir();pins=frameworks(a.user_dir)
src=a.user_dir/'libraries/ESP_Async_WebServer/src';header=(src/'WebResponseImpl.h').read_text();impl=(src/'WebResponses.cpp').read_text();region=load(ROOT/'tests/stage28v/prepare_sources.py','v_regions').region;pieces=[];evidence=[]
for text,file,pattern in [(header,'WebResponseImpl.h',r'class AsyncFileResponse\s*:\s*public AsyncAbstractResponse\s*\{'),(header,'WebResponseImpl.h',r'class AsyncProgmemResponse\s*:\s*public AsyncAbstractResponse\s*\{'),(impl,'WebResponses.cpp',r'AsyncFileResponse::AsyncFileResponse\(File content,[^{]+\{'),(impl,'WebResponses.cpp',r'size_t AsyncFileResponse::_fillBuffer\([^{}]*\)\s*\{'),(impl,'WebResponses.cpp',r'AsyncProgmemResponse::AsyncProgmemResponse\([^{}]*\)\s*\{'),(impl,'WebResponses.cpp',r'size_t AsyncProgmemResponse::_fillBuffer\([^{}]*\)\s*\{')]:
 start,end=region(text,pattern);body=text[start:end]+(';' if text[start:].startswith('class ') else '');line=text[:start].count('\n')+1;pieces.append('#line '+str(line)+' "'+str(src/file)+'"\n'+body);evidence.append(dict(file=file,line=line,body_sha256=__import__('hashlib').sha256(body.encode()).hexdigest()))
(a.output_dir/'framework_bodies.inc').write_text('\n'.join(pieces));exe=a.output_dir/'components';cmd=['g++','-std=c++17','-O1','-g','-fsanitize=address,undefined','-fno-omit-frame-pointer','-fno-pie','-no-pie','-Wall','-Wextra','-Werror','-Wno-misleading-indentation','-I'+str(a.output_dir),'-I'+str(ROOT/'tests/stage28w/mocks'),str(ROOT/'tests/stage28w/framework_test.cpp'),'-o',str(exe)];subprocess.run(cmd,check=True)
rows=[V.U.execute(exe,'F%02d'%i) for i in range(1,6)];r=dict(counts={s:sum(x['status']==s for x in rows) for s in ['PASS','FAIL']},assertions=sum(x['assertions'] for x in rows),results=rows,command=cmd,source_bodies=evidence,framework_pins=pins,scope='selected actual response class/constructor/read/destructor bodies; abstract base and File mocked; request disconnect ordering source-derived, request/TCP tasks NOT executed',sanitizers=V.U.T.ENV['ASAN_OPTIONS']+'; '+V.U.T.ENV['UBSAN_OPTIONS'],hardware=False)
(a.output_dir/'report.json').write_text(json.dumps(r,indent=2)+'\n');print(r['counts'],r['assertions']);raise SystemExit(bool(r['counts']['FAIL']))
